def seasons_and_no_review(apps, schema_editor):
    """Each document's season from the day it was added; the versions awaiting a review (draft or in review)
    are published, the latest becoming the current version: nothing is reviewed any more (D-020)."""
    Document = apps.get_model("documents", "Document")
    for document in Document.objects.all():
        day = timezone.localtime(document.created_at).date()
        document.season = day.year if day.month >= 9 else day.year - 1
        pending = document.versions.filter(status__in=["draft", "in_review"]).order_by("-number")
        latest = pending.first()
        pending.update(status="approved")
        fields = ["season"]
        if latest is not None and (document.current_version is None or latest.number > document.current_version.number):
            document.current_version = latest
            document.status = "approved"
            fields += ["current_version", "status"]
        document.save(update_fields=fields)


